/* MP04 metric XPBD batch kernel; actual same-frame body and garment triangles. */
typedef unsigned int u32; typedef signed short i16;
extern unsigned char __heap_base;
extern double atan2(double,double);
static u32 heap=0;
__attribute__((export_name("alloc"))) u32 alloc(u32 n){if(!heap)heap=(u32)&__heap_base;u32 p=(heap+15)&~15;heap=p+n;return p;}
void* memset(void*p,int v,u32 n){unsigned char*q=p;for(u32 i=0;i<n;i++)q[i]=v;return p;}
void* memcpy(void*p,const void*s,u32 n){unsigned char*q=p;const unsigned char*r=s;for(u32 i=0;i<n;i++)q[i]=r[i];return p;}
static double mn(double a,double b){return a<b?a:b;}static double mx(double a,double b){return a>b?a:b;}
static double clamp(double x,double a,double b){return mx(a,mn(b,x));}static double sq(double x){return x*x;}
static double len3(double x,double y,double z){return __builtin_sqrt(x*x+y*y+z*z);}
__attribute__((export_name("predict"))) void predict(double*p,double*v,double*old,double*w,int n,double h,double damp,double g){for(int i=0;i<n;i++){int j=3*i;for(int k=0;k<3;k++){old[j+k]=p[j+k];if(w[i])p[j+k]+=v[j+k]*damp*h;}if(w[i])p[j+1]-=g*h*h;}}
__attribute__((export_name("finish"))) int finish(double*p,double*v,double*old,double*w,int n,double h,double friction){for(int i=0;i<n;i++)for(int k=0;k<3;k++){int j=i*3+k;double d=(p[j]-old[j])/h;if(!__builtin_isfinite(d))return 0;v[j]=w[i]?clamp(d,-2,2)*friction:0;}return 1;}
__attribute__((export_name("reset_lambda"))) void reset_lambda(double*e,int n,int stride,int index){for(int i=0;i<n;i++)e[i*stride+index]=0;}
__attribute__((export_name("distance_batch"))) void distance_batch(double*p,double*w,double*edges,int n,double alpha){for(int i=0;i<n;i++){double*e=edges+i*4;int a=(int)e[0],b=(int)e[1],A=3*a,B=3*b;double dx=p[A]-p[B],dy=p[A+1]-p[B+1],dz=p[A+2]-p[B+2],l=len3(dx,dy,dz);if(l<1e-12)continue;double dl=(-(l-e[2])-alpha*e[3])/(w[a]+w[b]+alpha);e[3]+=dl;double f=dl/l;p[A]+=w[a]*dx*f;p[A+1]+=w[a]*dy*f;p[A+2]+=w[a]*dz*f;p[B]-=w[b]*dx*f;p[B+1]-=w[b]*dy*f;p[B+2]-=w[b]*dz*f;}}
__attribute__((export_name("strain_batch"))) void strain_batch(double*p,double*w,double*edges,int n,double lo,double hi){for(int i=0;i<n;i++){double*e=edges+i*4;int a=(int)e[0],b=(int)e[1],A=3*a,B=3*b;double dx=p[A]-p[B],dy=p[A+1]-p[B+1],dz=p[A+2]-p[B+2],l=len3(dx,dy,dz),target=clamp(l,e[2]*lo,e[2]*hi),ws=w[a]+w[b];if(l<1e-12||!ws||l==target)continue;double f=(target-l)/(l*ws);p[A]+=w[a]*dx*f;p[A+1]+=w[a]*dy*f;p[A+2]+=w[a]*dz*f;p[B]-=w[b]*dx*f;p[B+1]-=w[b]*dy*f;p[B+2]-=w[b]*dz*f;}}
__attribute__((export_name("bend_batch"))) void bend_batch(double*p,double*w,double*bends,int n,double alpha){for(int j=0;j<n;j++){double*b=bends+j*6;int ids[4]={(int)b[0],(int)b[1],(int)b[2],(int)b[3]},a=ids[0]*3,c=ids[1]*3,d=ids[2]*3,e=ids[3]*3;double ex=p[c]-p[a],ey=p[c+1]-p[a+1],ez=p[c+2]-p[a+2],ux=p[d]-p[a],uy=p[d+1]-p[a+1],uz=p[d+2]-p[a+2],vx=p[e]-p[a],vy=p[e+1]-p[a+1],vz=p[e+2]-p[a+2];double nx=ey*uz-ez*uy,ny=ez*ux-ex*uz,nz=ex*uy-ey*ux,mx0=vy*ez-vz*ey,my=vz*ex-vx*ez,mz=vx*ey-vy*ex,e2=ex*ex+ey*ey+ez*ez,n2=nx*nx+ny*ny+nz*nz,m2=mx0*mx0+my*my+mz*mz;if(mn(e2,mn(n2,m2))<1e-18)continue;double L=__builtin_sqrt(e2),u=(ux*ex+uy*ey+uz*ez)/e2,v=(vx*ex+vy*ey+vz*ez)/e2;double q[12];q[6]=-L*nx/n2;q[7]=-L*ny/n2;q[8]=-L*nz/n2;q[9]=-L*mx0/m2;q[10]=-L*my/m2;q[11]=-L*mz/m2;for(int k=0;k<3;k++){q[3+k]=-u*q[6+k]-v*q[9+k];q[k]=-q[3+k]-q[6+k]-q[9+k];}double C=atan2((ex*(ny*mz-nz*my)+ey*(nz*mx0-nx*mz)+ez*(nx*my-ny*mx0))/L,nx*mx0+ny*my+nz*mz)-b[5],den=alpha;for(int i=0;i<4;i++)for(int k=0;k<3;k++)den+=w[ids[i]]*q[i*3+k]*q[i*3+k];double dl=(-C-alpha*b[4])/den;b[4]+=dl;for(int i=0;i<4;i++)for(int k=0;k<3;k++)p[ids[i]*3+k]+=w[ids[i]]*q[i*3+k]*dl;}}
static void sdf_sample(i16*d,double*m,double x,double y,double z,double*q){int nx=(int)m[0],ny=(int)m[1],nz=(int)m[2];double h=m[6],gx=(x*1000-m[3])/h,gy=((y+m[8])*1000-m[4])/h,gz=(z*1000-m[5])/h;if(gx<0||gy<0||gz<0||gx>=nx-1||gy>=ny-1||gz>=nz-1){q[0]=1e20;q[1]=q[2]=q[3]=0;return;}int ix=(int)gx,iy=(int)gy,iz=(int)gz,s=nx*ny,k=ix+nx*iy+s*iz;double fx=gx-ix,fy=gy-iy,fz=gz-iz,a=d[k],b=d[k+1],c=d[k+nx],e=d[k+nx+1],f=d[k+s],g=d[k+s+1],j=d[k+s+nx],l=d[k+s+nx+1],ab=a+(b-a)*fx,ce=c+(e-c)*fx,fg=f+(g-f)*fx,jl=j+(l-j)*fx,low=ab+(ce-ab)*fy,high=fg+(jl-fg)*fy;q[0]=(low+(high-low)*fz)*m[7]*.001;q[1]=((b-a)*(1-fy)*(1-fz)+(e-c)*fy*(1-fz)+(g-f)*(1-fy)*fz+(l-j)*fy*fz)*m[7]/h;q[2]=((ce-ab)*(1-fz)+(jl-fg)*fz)*m[7]/h;q[3]=(high-low)*m[7]/h;}
static void closest(double*p,int*F,int f,double x,double y,double z,double*q){int ia=F[f]*3,ib=F[f+1]*3,ic=F[f+2]*3;double ax=p[ia],ay=p[ia+1],az=p[ia+2],ux=p[ib]-ax,uy=p[ib+1]-ay,uz=p[ib+2]-az,vx=p[ic]-ax,vy=p[ic+1]-ay,vz=p[ic+2]-az,wx=x-ax,wy=y-ay,wz=z-az,uu=ux*ux+uy*uy+uz*uz,vv=vx*vx+vy*vy+vz*vz,uv=ux*vx+uy*vy+uz*vz,wu=wx*ux+wy*uy+wz*uz,wv=wx*vx+wy*vy+wz*vz,den=uu*vv-uv*uv,b=den>1e-24?(wu*vv-wv*uv)/den:0,c=den>1e-24?(wv*uu-wu*uv)/den:0;if(b<0||c<0||b+c>1||den<=1e-24){double best=1e30,B=0,C=0;for(int k=0;k<3;k++){double sx=0,sy=0,sz=0,ex=ux,ey=uy,ez=uz;if(k==1){sx=ux;sy=uy;sz=uz;ex=vx-ux;ey=vy-uy;ez=vz-uz;}else if(k==2){sx=vx;sy=vy;sz=vz;ex=-vx;ey=-vy;ez=-vz;}double t=clamp(((wx-sx)*ex+(wy-sy)*ey+(wz-sz)*ez)/mx(1e-24,ex*ex+ey*ey+ez*ez),0,1),d=sq(sx+t*ex-wx)+sq(sy+t*ey-wy)+sq(sz+t*ez-wz);if(d<best){best=d;B=k==0?t:k==1?1-t:0;C=k==0?0:k==1?t:1-t;}}b=B;c=C;}q[1]=ax+ux*b+vx*c;q[2]=ay+uy*b+vy*c;q[3]=az+uz*b+vz*c;q[0]=sq(x-q[1])+sq(y-q[2])+sq(z-q[3]);q[4]=1-b-c;q[5]=b;q[6]=c;}
__attribute__((export_name("refit"))) void refit(double*p,int*F,int nFaces,double*N,double*nodes,int nNodes,int*order,int count){for(int i=0;i<count*3;i++)N[i]=0;for(int f=0;f<nFaces*3;f+=3){int a=F[f]*3,b=F[f+1]*3,c=F[f+2]*3;double ux=p[b]-p[a],uy=p[b+1]-p[a+1],uz=p[b+2]-p[a+2],vx=p[c]-p[a],vy=p[c+1]-p[a+1],vz=p[c+2]-p[a+2],nn[3]={uy*vz-uz*vy,uz*vx-ux*vz,ux*vy-uy*vx};for(int i=0;i<3;i++)for(int k=0;k<3;k++)N[F[f+i]*3+k]+=nn[k];}for(int i=0;i<count*3;i+=3){double L=mx(1e-24,len3(N[i],N[i+1],N[i+2]));N[i]/=L;N[i+1]/=L;N[i+2]/=L;}for(int j=nNodes-1;j>=0;j--){double*n=nodes+j*10;for(int k=0;k<3;k++){n[k+4]=1e30;n[k+7]=-1e30;}if(n[2]>=0){double*a=nodes+(int)n[2]*10,*b=nodes+(int)n[3]*10;for(int k=0;k<3;k++){n[k+4]=mn(a[k+4],b[k+4]);n[k+7]=mx(a[k+7],b[k+7]);}}else for(int i=(int)n[0];i<(int)n[1];i++){int f=order[i];for(int v=0;v<3;v++)for(int k=0;k<3;k++){double x=p[F[f+v]*3+k];n[k+4]=mn(n[k+4],x);n[k+7]=mx(n[k+7],x);}}}}
static int nearest(double*p,int*F,double*nodes,int*order,double x,double y,double z,double maxd,int seed,double*q){int stack[128],head=1,winner=-1;stack[0]=0;double best=maxd*maxd,tmp[7];if(seed>=0){closest(p,F,seed,x,y,z,tmp);if(tmp[0]<best){best=tmp[0];winner=seed;for(int k=0;k<7;k++)q[k]=tmp[k];}}while(head){double*n=nodes+stack[--head]*10,dx=mx(0,mx(n[4]-x,x-n[7])),dy=mx(0,mx(n[5]-y,y-n[8])),dz=mx(0,mx(n[6]-z,z-n[9]));if(dx*dx+dy*dy+dz*dz>best)continue;if(n[2]<0){for(int i=(int)n[0];i<(int)n[1];i++){int f=order[i];closest(p,F,f,x,y,z,tmp);if(tmp[0]<best){best=tmp[0];winner=f;for(int k=0;k<7;k++)q[k]=tmp[k];}}}else{double*a=nodes+(int)n[2]*10,*b=nodes+(int)n[3]*10,da=sq(a[4]+a[7]-2*x)+sq(a[5]+a[8]-2*y)+sq(a[6]+a[9]-2*z),db=sq(b[4]+b[7]-2*x)+sq(b[5]+b[8]-2*y)+sq(b[6]+b[9]-2*z);if(da<db){stack[head++]=(int)n[3];stack[head++]=(int)n[2];}else{stack[head++]=(int)n[2];stack[head++]=(int)n[3];}}}return winner;}
static void mesh_sample(double*p,double*N,int*F,double*nodes,int*order,double x,double y,double z,int*cache,int refresh,double*out){double q[7];int f=*cache;if(refresh||f<0)f=*cache=nearest(p,F,nodes,order,x,y,z,1e20,f,q);else closest(p,F,f,x,y,z,q);if(f<0){out[0]=1e20;return;}double nn[3]={0,0,0};for(int j=0;j<3;j++)for(int k=0;k<3;k++)nn[k]+=N[F[f+j]*3+k]*q[j+4];double dx=x-q[1],dy=y-q[2],dz=z-q[3],dot=dx*nn[0]+dy*nn[1]+dz*nn[2],L=__builtin_sqrt(q[0]),sign=dot<0?-1:1;out[0]=L*sign;if(L>1e-10){out[1]=dx*sign/L;out[2]=dy*sign/L;out[3]=dz*sign/L;}else{L=mx(1e-24,len3(nn[0],nn[1],nn[2]));for(int k=0;k<3;k++)out[k+1]=nn[k]/L;}}
static void sample(int kind,i16*S,double*M,double*P,double*N,int*F,double*B,int*O,double x,double y,double z,int*cache,int refresh,double*q){if(kind)mesh_sample(P,N,F,B,O,x,y,z,cache,refresh,q);else sdf_sample(S,M,x,y,z,q);}
__attribute__((export_name("body_project"))) int body_project(double*p,double*w,int count,int*faces,int nf,double*edges,int ne,int kind,i16*S,double*M,double*P,double*N,int*F,double*B,int*O,int*cache,double margin,int refresh,int dense){int contacts=0;double q[4];for(int i=0;i<count;i++){if(!w[i])continue;int j=i*3;sample(kind,S,M,P,N,F,B,O,p[j],p[j+1],p[j+2],cache+i,refresh,q);if(q[0]<margin){double g2=sq(q[1])+sq(q[2])+sq(q[3]);if(g2<.01)continue;double dl=mn(.008,margin-q[0])/g2;for(int k=0;k<3;k++)p[j+k]+=q[k+1]*dl;contacts++;}}
 if(dense){for(int mode=0;mode<2;mode++){int n=mode?nf:ne,m=mode?3:2;for(int i=0;i<n;i++){int ids[3];if(mode){ids[0]=faces[i*3];ids[1]=faces[i*3+1];ids[2]=faces[i*3+2];}else{ids[0]=(int)edges[i*4];ids[1]=(int)edges[i*4+1];}double x=0,y=0,z=0,ws=0;for(int j=0;j<m;j++){x+=p[ids[j]*3]/m;y+=p[ids[j]*3+1]/m;z+=p[ids[j]*3+2]/m;ws+=w[ids[j]]/m/m;}if(!ws)continue;int*slot=cache+count+(mode?ne:0)+i;sample(kind,S,M,P,N,F,B,O,x,y,z,slot,refresh||*slot<0,q);double target=margin+.0008;if(q[0]<target){double g2=sq(q[1])+sq(q[2])+sq(q[3]);if(g2<.01)continue;double dl=mn(.008,target-q[0])/g2/ws;for(int j=0;j<m;j++)for(int k=0;k<3;k++)p[ids[j]*3+k]+=w[ids[j]]/m*dl*q[k+1];contacts++;}}}}
 return contacts;}
__attribute__((export_name("pair_project"))) int pair_project(double*p,double*w,int n,double*P,double*W,double*N,int*F,double*B,int*O,int*cache,double gap,int refresh,int oneWay){int count=0;double q[7];for(int i=0;i<n;i++){if(!w[i])continue;int j=i*3;double x=p[j],y=p[j+1],z=p[j+2];if(x<B[4]-.04||x>B[7]+.04||y<B[5]-.04||y>B[8]+.04||z<B[6]-.04||z>B[9]+.04)continue;int f=cache[i];if(refresh||f<0)f=cache[i]=nearest(P,F,B,O,x,y,z,.045,f,q);else closest(P,F,f,x,y,z,q);if(f<0||q[0]>.045*.045)continue;int a=F[f]*3,b=F[f+1]*3,c=F[f+2]*3;double ux=P[b]-P[a],uy=P[b+1]-P[a+1],uz=P[b+2]-P[a+2],vx=P[c]-P[a],vy=P[c+1]-P[a+1],vz=P[c+2]-P[a+2],nx=uy*vz-uz*vy,ny=uz*vx-ux*vz,nz=ux*vy-uy*vx,L=len3(nx,ny,nz);if(L<1e-12)continue;nx/=L;ny/=L;nz/=L;double d=(x-q[1])*nx+(y-q[2])*ny+(z-q[3])*nz;if(d>=gap||d<-.035||q[0]-d*d>gap*gap)continue;double ws=w[i];if(!oneWay)for(int k=0;k<3;k++)ws+=sq(q[k+4])*W[F[f+k]];double dl=mn(.012,gap-d)/ws;p[j]+=nx*dl*w[i];p[j+1]+=ny*dl*w[i];p[j+2]+=nz*dl*w[i];if(!oneWay)for(int k=0;k<3;k++){int id=F[f+k];double t=dl*q[k+4]*W[id];P[id*3]-=nx*t;P[id*3+1]-=ny*t;P[id*3+2]-=nz*t;}count++;}return count;}
__attribute__((export_name("query_mesh"))) void query_mesh(double*p,double*N,int*F,double*B,int*O,double x,double y,double z,double*q){int cache=-1;mesh_sample(p,N,F,B,O,x,y,z,&cache,1,q);}


/* MP04.2 interior garment contact, not just vertex-versus-surface distances. */
__attribute__((export_name("pair_surface"))) int pair_surface(double*p,double*w,int*faces,int nf,double*edges,int ne,double*P,double*W,double*N,int*F,double*B,int*O,int*cache,double gap,int refresh,int oneWay){
 int count=0;double q[7];
 for(int mode=0;mode<2;mode++)for(int i=0;i<(mode?nf:ne);i++){
  int ids[3],m=mode?3:2;if(mode){ids[0]=faces[i*3];ids[1]=faces[i*3+1];ids[2]=faces[i*3+2];}else{ids[0]=(int)edges[i*4];ids[1]=(int)edges[i*4+1];}
  double x=0,y=0,z=0,wa=0;for(int k=0;k<m;k++){x+=p[ids[k]*3]/m;y+=p[ids[k]*3+1]/m;z+=p[ids[k]*3+2]/m;wa+=w[ids[k]]/m/m;}
  if(!wa||x<B[4]-.04||x>B[7]+.04||y<B[5]-.04||y>B[8]+.04||z<B[6]-.04||z>B[9]+.04)continue;
  int ci=(mode?ne:0)+i,f=cache[ci];if(refresh||f<0)f=cache[ci]=nearest(P,F,B,O,x,y,z,.045,f,q);else closest(P,F,f,x,y,z,q);
  if(f<0||q[0]>.045*.045)continue;
  int a=F[f]*3,b=F[f+1]*3,c=F[f+2]*3;double ux=P[b]-P[a],uy=P[b+1]-P[a+1],uz=P[b+2]-P[a+2],vx=P[c]-P[a],vy=P[c+1]-P[a+1],vz=P[c+2]-P[a+2],nx=uy*vz-uz*vy,ny=uz*vx-ux*vz,nz=ux*vy-uy*vx,L=len3(nx,ny,nz);if(L<1e-12)continue;
  nx/=L;ny/=L;nz/=L;double d=(x-q[1])*nx+(y-q[2])*ny+(z-q[3])*nz;if(d>=gap||d<-.035||q[0]-d*d>gap*gap)continue;
  double ws=wa;if(!oneWay)for(int k=0;k<3;k++)ws+=sq(q[k+4])*W[F[f+k]];
  double dl=mn(.012,gap-d)/ws;for(int k=0;k<m;k++){double t=w[ids[k]]*dl/m;p[ids[k]*3]+=nx*t;p[ids[k]*3+1]+=ny*t;p[ids[k]*3+2]+=nz*t;}
  if(!oneWay)for(int k=0;k<3;k++){int id=F[f+k];double t=dl*q[k+4]*W[id];P[id*3]-=nx*t;P[id*3+1]-=ny*t;P[id*3+2]-=nz*t;}count++;
 }
 return count;
}
